// --- VERSION 0.0.3.0 ---
// DriveReplay (v7-compatible):
// - MapLibre heading-up map (react-map-gl/maplibre + maplibregl instance)
// - Dynamic zoom (avg speed)
// - Dynamic min/max per-trip speed coloring
// - Real-time playback using timestamp deltas (±1x, ±2x, ±5x, 0x)
// - Zoomable chart + playback marker (chartjs-plugin-zoom + annotation)
// - Full-viewport layout (detached from dashboard wrappers)

import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { useParams, Link } from 'react-router-dom';

import Map from 'react-map-gl/maplibre';
import { Source, Layer, Marker } from 'react-map-gl';
import maplibregl from 'maplibre-gl';
import 'maplibre-gl/dist/maplibre-gl.css';

import { Line } from 'react-chartjs-2';
import {
  Chart as ChartJS, CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend
} from 'chart.js';
import zoomPlugin from 'chartjs-plugin-zoom';
import annotationPlugin from 'chartjs-plugin-annotation';

ChartJS.register(CategoryScale, LinearScale, PointElement, LineElement, Title, Tooltip, Legend, zoomPlugin, annotationPlugin);

const MAP_STYLE = 'https://basemaps.cartocdn.com/gl/dark-matter-gl-style/style.json';

function clamp(v, lo, hi) { return Math.max(lo, Math.min(hi, v)); }

function trimIdleEnds(rows, speedKey = 'gps_speed') {
  if (!Array.isArray(rows) || rows.length === 0) return rows;
  const sp = (v) => Number(v) || 0;

  let intervalSec = 1;
  if (rows.length > 1 && rows[0]?.timestamp != null && rows[1]?.timestamp != null) {
    const d = Math.abs(Number(rows[1].timestamp) - Number(rows[0].timestamp));
    intervalSec = d > 1000 ? d / 1000 : (d || 1);
  }
  const thresholdMph = 1.0;
  const idleSamples = Math.max(1, Math.ceil(10 / intervalSec));

  let s = 0;
  while (s + idleSamples < rows.length &&
         rows.slice(s, s + idleSamples).every(r => sp(r[speedKey]) <= thresholdMph)) s++;

  let e = rows.length - 1;
  while (e - idleSamples >= s &&
         rows.slice(e - idleSamples + 1, e + 1).every(r => sp(r[speedKey]) <= thresholdMph)) e--;

  return rows.slice(s, e + 1);
}

export default function DriveReplay() {
  const { logId } = useParams();
  const [log, setLog] = useState(null);
  const [loading, setLoading] = useState(true);
  const [err, setErr] = useState(null);

  const [selectedPIDs, setSelectedPIDs] = useState(['gps_speed', 'engine_rpm', 'instant_fuel_economy']);
  const [playState, setPlayState] = useState({ playing: false, rate: 1 }); // -5,-2,-1,0,1,2,5
  const [cursorIdx, setCursorIdx] = useState(0);
  const timerRef = useRef(null);

  useEffect(() => {
    let mounted = true;
    setLoading(true);
    setErr(null);
    fetch(`/api/logs/${logId}/data`)
      .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .then(data => {
        if (!mounted) return;
        const rows = Array.isArray(data?.data) ? data.data : [];
        const trimmed = trimIdleEnds(rows, 'gps_speed');
        const columns = Array.isArray(data?.columns) ? data.columns : (trimmed[0] ? Object.keys(trimmed[0]) : []);
        setLog({ data: trimmed, columns });
        setCursorIdx(0);
      })
      .catch(e => { if (mounted) setErr(e.message || 'Failed to load'); })
      .finally(() => { if (mounted) setLoading(false); });
    return () => { mounted = false; };
  }, [logId]);

  const points = useMemo(() => (log?.data || [])
    .map(r => [Number(r?.latitude), Number(r?.longitude)])
    .filter(([lat, lon]) => Number.isFinite(lat) && Number.isFinite(lon) && lat !== 0 && lon !== 0), [log]);

  const speeds = useMemo(() => (log?.data || []).map(r => Number(r?.gps_speed) || 0), [log]);
  const minSpeed = useMemo(() => speeds.length ? Math.min(...speeds) : 0, [speeds]);
  const maxSpeed = useMemo(() => speeds.length ? Math.max(...speeds) : 0, [speeds]);
  const avgSpeed = useMemo(() => speeds.length ? speeds.reduce((a, b) => a + b, 0) / speeds.length : 0, [speeds]);

  const colorForSpeed = useCallback((mph) => {
    const ratio = (mph - minSpeed) / (maxSpeed - minSpeed || 1);
    if (ratio <= 0.25) return '#3B82F6';   // blue
    if (ratio <= 0.5) return '#22C55E';    // green
    if (ratio <= 0.75) return '#F59E0B';   // amber
    return '#EF4444';                      // red
  }, [minSpeed, maxSpeed]);

  const lineSegments = useMemo(() => {
    const segs = [];
    for (let i = 1; i < points.length; i++) {
      segs.push({
        id: `seg-${i}`,
        geojson: {
          type: 'FeatureCollection',
          features: [{
            type: 'Feature',
            geometry: { type: 'LineString', coordinates: [[points[i - 1][1], points[i - 1][0]], [points[i][1], points[i][0]]] },
            properties: {}
          }]
        },
        color: colorForSpeed(speeds[i])
      });
    }
    return segs;
  }, [points, speeds, colorForSpeed]);

  const chartData = useMemo(() => {
    if (!log?.data) return { labels: [], datasets: [] };
    const labels = log.data.map((_, i) => i);
    return {
      labels,
      datasets: selectedPIDs.filter(Boolean).filter(p => p !== 'none').map((pid, i) => ({
        label: pid,
        data: log.data.map(r => {
          const n = Number(r?.[pid]);
          return Number.isFinite(n) ? n : null;
        }),
        borderColor: ['#38BDF8', '#F59E0B', '#A78BFA', '#22C55E', '#EF4444'][i % 5],
        backgroundColor: 'transparent',
        borderWidth: 2,
        pointRadius: 0,
        tension: 0.3
      }))
    };
  }, [log, selectedPIDs]);
  const chartOptions = useMemo(() => ({
    responsive: true,
    maintainAspectRatio: false,
    animation: false,
    plugins: {
      zoom: {
        zoom: { wheel: { enabled: true }, pinch: { enabled: true }, mode: 'x' },
        pan: { enabled: true, mode: 'x' }
      },
      annotation: {
        annotations: {
          playbackLine: {
            type: 'line',
            xMin: cursorIdx,
            xMax: cursorIdx,
            borderColor: '#F87171',
            borderWidth: 2
          }
        }
      },
      legend: { labels: { color: '#9CA3AF' } },
      tooltip: { enabled: true }
    },
    scales: {
      x: { ticks: { color: '#9CA3AF' } },
      y: { ticks: { color: '#9CA3AF' } }
    }
  }), [cursorIdx]);

  const currentRow = log?.data?.[cursorIdx] || {};
  const cursorPos = [Number(currentRow?.latitude), Number(currentRow?.longitude)];

  const heading = useMemo(() => {
    if (cursorIdx < 1 || points.length < 2) return 0;
    const [lat1, lon1] = points[cursorIdx - 1];
    const [lat2, lon2] = points[cursorIdx];
    const toRad = (d) => d * Math.PI / 180;
    const y = Math.sin(toRad(lon2 - lon1)) * Math.cos(toRad(lat2));
    const x = Math.cos(toRad(lat1)) * Math.sin(toRad(lat2)) -
              Math.sin(toRad(lat1)) * Math.cos(toRad(lat2)) * Math.cos(toRad(lon2 - lon1));
    return (Math.atan2(y, x) * 180 / Math.PI + 360) % 360;
  }, [cursorIdx, points]);

  // Real-time playback pacing by timestamp delta
  useEffect(() => {
    if (!log?.data || !playState.playing) return;
    const step = Math.sign(playState.rate);
    if (step === 0) return;
    const curTs = Number(log.data[cursorIdx]?.timestamp);
    const nextTs = Number(log.data[cursorIdx + step]?.timestamp);
    if (!Number.isFinite(curTs) || !Number.isFinite(nextTs)) return;
    const deltaMs = Math.max(10, Math.abs(nextTs - curTs) / Math.abs(playState.rate));
    timerRef.current = setTimeout(() => {
      setCursorIdx(i => clamp(i + step, 0, log.data.length - 1));
    }, deltaMs);
    return () => { if (timerRef.current) clearTimeout(timerRef.current); };
  }, [cursorIdx, playState, log]);

  const setRate = useCallback((rate) => setPlayState(s => ({ ...s, rate })), []);
  const playPause = useCallback(() => setPlayState(s => ({ ...s, playing: !s.playing })), []);
  const stop = useCallback(() => {
    setPlayState({ playing: false, rate: 1 });
    setCursorIdx(0);
  }, []);
  const stepRelative = useCallback((dx) => {
    setPlayState(s => ({ ...s, playing: false }));
    setCursorIdx(prev => clamp(prev + dx, 0, (log?.data?.length ?? 1) - 1));
  }, [log]);

  useEffect(() => {
    const onKey = (e) => {
      if (e.key === ' ') { e.preventDefault(); playPause(); }
      else if (e.key === 'ArrowRight') stepRelative(+5);
      else if (e.key === 'ArrowLeft') stepRelative(-5);
      else if (e.key === '1') setRate(1);
      else if (e.key === '2') setRate(2);
      else if (e.key === '5') setRate(5);
      else if (e.key === 'q') setRate(-1);
      else if (e.key === 'w') setRate(-2);
      else if (e.key === 'e') setRate(-5);
      else if (e.key === '0') setRate(0);
    };
    window.addEventListener('keydown', onKey);
    return () => window.removeEventListener('keydown', onKey);
  }, [playPause, stepRelative, setRate]);

  const handlePidChange = useCallback((idx, val) => {
    setSelectedPIDs(prev => { const next = [...prev]; next[idx] = val; return next; });
  }, []);

  if (loading) {
    return (
      <div className="fixed inset-0 flex items-center justify-center bg-gray-900 text-white">
        <div>
          <div className="animate-spin w-10 h-10 border-4 border-cyan-400 border-t-transparent rounded-full mx-auto mb-4"></div>
          Loading replay...
        </div>
      </div>
    );
  }

  if (err || !log?.data?.length) {
    return (
      <div className="fixed inset-0 flex items-center justify-center bg-gray-900 text-white">
        <div className="text-center">
          <div className="text-red-400 font-semibold mb-2">Unable to load log</div>
          <div className="text-sm text-gray-400 mb-4">{err || 'No data'}</div>
          <Link to={`/logs/${logId}`} className="text-cyan-400 hover:text-cyan-300 underline">Back to Log</Link>
        </div>
      </div>
    );
  }

  const pidOptions = log.columns;
  const dynamicZoom = avgSpeed < 15 ? 17 : avgSpeed < 35 ? 16 : avgSpeed < 55 ? 15 : 14;

  return (
    <div className="fixed inset-0 bg-gray-900 text-white overflow-hidden">
      {/* Top overlay: controls */}
      <div className="absolute top-0 left-0 right-0 z-20 bg-gray-900/70 backdrop-blur px-4 py-2 flex items-center gap-3">
        <Link to={`/logs/${logId}`} className="text-cyan-400 hover:text-cyan-300 underline">← Back</Link>
        <div className="flex items-center gap-2 text-sm">
          <button onClick={playPause} className="px-2 py-1 bg-gray-700 rounded hover:bg-gray-600">
            {playState.playing ? 'Pause' : 'Play'}
          </button>
          <button onClick={stop} className="px-2 py-1 bg-gray-700 rounded hover:bg-gray-600">Stop</button>
          <button onClick={() => setRate(-5)} className={`px-2 py-1 rounded ${playState.rate===-5?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-5x</button>
          <button onClick={() => setRate(-2)} className={`px-2 py-1 rounded ${playState.rate===-2?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-2x</button>
          <button onClick={() => setRate(-1)} className={`px-2 py-1 rounded ${playState.rate===-1?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>-1x</button>
          <button onClick={() => setRate(0)} className={`px-2 py-1 rounded ${playState.rate===0?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>0x</button>
          <button onClick={() => setRate(1)} className={`px-2 py-1 rounded ${playState.rate===1?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>1x</button>
          <button onClick={() => setRate(2)} className={`px-2 py-1 rounded ${playState.rate===2?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>2x</button>
          <button onClick={() => setRate(5)} className={`px-2 py-1 rounded ${playState.rate===5?'bg-cyan-700':'bg-gray-700 hover:bg-gray-600'}`}>5x</button>
        </div>
      </div>
      {/* Map (heading-up, dynamic zoom) */}
      <div className="absolute inset-0 z-0">
        <Map
          mapLib={maplibregl}
          initialViewState={{
            latitude: cursorPos[0] || 44.97,
            longitude: cursorPos[1] || -93.26,
            zoom: dynamicZoom,
            bearing: heading,
            pitch: 0
          }}
          viewState={{
            latitude: cursorPos[0] || 44.97,
            longitude: cursorPos[1] || -93.26,
            zoom: dynamicZoom,
            bearing: heading,
            pitch: 0
          }}
          style={{ width: '100%', height: '100%' }}
          mapStyle={MAP_STYLE}
        >
          {/* Context path (dim) */}
          {points.length > 1 && (
            <Source
              id="context-path"
              type="geojson"
              data={{
                type: 'Feature',
                geometry: { type: 'LineString', coordinates: points.map(p => [p[1], p[0]]) }
              }}
            >
              <Layer id="context-line" type="line" paint={{ 'line-color': '#4B5563', 'line-width': 2, 'line-opacity': 0.5 }} />
            </Source>
          )}

          {/* Speed-colored segments */}
          {lineSegments.map(seg => (
            <Source key={seg.id} id={seg.id} type="geojson" data={seg.geojson}>
              <Layer id={`${seg.id}-layer`} type="line" paint={{ 'line-color': seg.color, 'line-width': 4, 'line-opacity': 0.9 }} />
            </Source>
          ))}

          {/* Cursor marker */}
          {Number.isFinite(cursorPos[0]) && Number.isFinite(cursorPos[1]) && (
            <Marker latitude={cursorPos[0]} longitude={cursorPos[1]} anchor="center">
              <div className="w-3 h-3 bg-white rounded-full border-2 border-black" />
            </Marker>
          )}
        </Map>
      </div>

      {/* Gauges overlay */}
      <div className="absolute bottom-4 left-4 z-20 grid grid-cols-2 md:grid-cols-4 gap-3">
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">GPS Speed</div>
          <div className="text-3xl font-bold" style={{ color: colorForSpeed(Number(currentRow.gps_speed) || 0) }}>
            {Number.isFinite(Number(currentRow.gps_speed)) ? Number(currentRow.gps_speed).toFixed(0) : '—'}
            <span className="text-base text-gray-400"> mph</span>
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Engine RPM</div>
          <div className="text-3xl font-bold text-cyan-300">
            {Number.isFinite(Number(currentRow.engine_rpm)) ? Number(currentRow.engine_rpm).toFixed(0) : '—'}
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Adapter Volts</div>
          <div className="text-3xl font-bold text-amber-300">
            {Number.isFinite(Number(currentRow.adapter_voltage)) ? Number(currentRow.adapter_voltage).toFixed(1) : '—'}
            <span className="text-base text-gray-400"> V</span>
          </div>
        </div>
        <div className="bg-gray-800/90 rounded p-3 min-w-[130px]">
          <div className="text-xs text-gray-400">Instant MPG</div>
          <div className="text-3xl font-bold text-emerald-300">
            {Number.isFinite(Number(currentRow.instant_fuel_economy)) ? Number(currentRow.instant_fuel_economy).toFixed(1) : '—'}
          </div>
        </div>
      </div>

      {/* Compass / position overlay */}
      <div className="absolute top-14 left-4 z-20 bg-gray-800/90 rounded p-2 text-xs text-gray-300">
        <div className="font-mono">Index {cursorIdx + 1}/{log.data.length}</div>
        <div className="font-mono">
          Lat/Lon: {Number.isFinite(cursorPos[0]) && Number.isFinite(cursorPos[1]) ? `${cursorPos[0].toFixed(5)}, ${cursorPos[1].toFixed(5)}` : '—'}
        </div>
        <div className="font-mono">Heading: {heading.toFixed(0)}°</div>
      </div>
      {/* PID selectors + zoomable chart overlay */}
      <div className="absolute top-12 right-4 z-20 bg-gray-900/90 rounded-lg p-3 w-[32vw] min-w-[320px] h-[28vh]">
        <div className="flex gap-2 mb-2">
          {selectedPIDs.map((pid, i) => (
            <select
              key={i}
              className="bg-gray-700 text-gray-100 text-xs px-2 py-1 rounded w-1/3"
              value={pid}
              onChange={(e) => handlePidChange(i, e.target.value)}
            >
              <option value="none">none</option>
              {pidOptions.map(opt => (
                <option key={opt} value={opt}>{opt}</option>
              ))}
            </select>
          ))}
        </div>
        <div className="w-full h-[22vh]">
          <Line data={chartData} options={chartOptions} />
        </div>
      </div>

      {/* Scrub bar */}
      <div className="absolute bottom-4 left-1/2 -translate-x-1/2 z-20 w-[60vw] min-w-[320px]">
        <input
          type="range"
          min="0"
          max={(log.data.length - 1).toString()}
          value={cursorIdx}
          onChange={(e) => {
            setPlayState(s => ({ ...s, playing: false }));
            setCursorIdx(Number(e.target.value));
          }}
          className="w-full accent-cyan-400"
        />
      </div>
    </div>
  );
}
